	&:= \|A_{21}\| \| \hat{\bm{\mu}} - \bm{\mu}_{0}\|, 
\end{align*}
where $  M_i =   - Y_i + 2\beta A_i +\bm{V}_i^T \bm{\lambda}_{0} - 2\beta \bm{V}_i^T \bm{\mu}_{0}    $. We use \citet[Theorem 1]{tropp2015expected} and Markov inequality to construct a bound for $ \|A_{21}\| $. From Theorem 1 of \cite{tropp2015expected}, we need to calculate the matrix variance parameter $ v= \| E ( A_{21} A_{21}^T )\| $ and the large deviation parameter $ L= \{ E \max_i \|S_i\|^2 \}^{1/2} $, where $  S_i = n^{-1}\big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \bm{V}_i^T M_i $. 


 Note that 
 \begin{align*}
 	v& = n \| E( S_i S_i^T) \|\\
 	&=  n^{-1} \left\|  E\left\{ \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  
 	\big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)^T M_i^2  \bm{V}_i^T\bm{V}_i   \right\}   \right\| \\
 	&\leq C n^{-1} m  \left\|  E\left\{ 
 \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)^T M_i^2   \right\}   \right\|   \\
 	& \leq C n^{-1} m
 \end{align*}
 where the third line is from $ \bm{V}_i $ being bounded, the last line is from Assumption \ref{assump:omega}.  Also note that
\begin{align*}
& \left\| \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \bm{V}_i^T \right\|^2  = \xi_{\max} \left\{ \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \bm{V}_i^T  \bm{V}_i   \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big) ^T \right\}\\
&\leq tr \left\{ \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \bm{V}_i^T  \bm{V}_i    \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big) ^T \right\}  \leq Cm \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big) ^T \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \\
&= Cm \sum_{j=1}^m (Z_{ij } - \bm{X}_i^T \bm\pi_{j0} )^2\leq Cm^2,
\end{align*}
and the last two inequalities are from $\bm{V}_i$ being bounded. This implies that 
\begin{align*}
	L^2&= E\max_i \|S_i\|^2 =n^{-2}   E\left \{ \max_i  \left\| \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)   \bm{V}_i^T \right\|^2 M_i^2 \right \} \\
	& \leq C  n^{-2} m^2 E(\max_i M_i^2) \leq C  n^{-2} m^2 E \{\max_i (Y_i^2+A_i^2) \}\leq Cn^{-2} m^2 (\log n)^2,
\end{align*}
where the last inequality is from $E \{\max_i (Y_i^2+A_i^2) \} \leq E \{\max_i (Y_i^2)\} + E\{ \max_i(A_i^2) \}   \leq C (\log n)^2$, which uses \citet[Lemma 14.12]{buhlmann2011statistics} with $n=1$ and $m=2$.


From the above analysis and Theorem 1 of \cite{tropp2015expected}, we know the matrix variance parameter $ v $ is driving the upper bound and 
\begin{align*}
	E \|A_{21} \|^2 \leq C\log (m)  v \leq C \frac{m \log m}{n}. 
\end{align*}
Then, from Markov inequality, we know that  $  \|A_{21}\|^2= O_p( m\log m /n )$.  Using the same argument as the proof of $ \|\hat{\bm\pi}_j -   {\bm\pi}_{j0} \| $  in \eqref{eq: pi}, we can show that $ \|\hat{\bm \mu}- \bm\mu_0 \| = O_p( \sqrt{m\log m/n} )$. Thus,  $\| A_{2} \| =  O_p( m \log m/n ) $.  The last term $ A_3 $ is bounded using the same argument. 

 Finally, as the remainder term $ \text{Rem}_a $ consists of higher order terms, we can use the above arguments to show that  $ \text{Rem}_a $  is negligible. This concludes the proof of part (a). 

For part (b), we want to show that   $ \| \hat g(\beta_0,  \hat \bm \eta) -   \hat 	g( \beta_0, \hat \bm \eta_{p},  \bm \eta_{np0})  \|=o_p(n^{-1/2}) + o_p(m\sqrt{\log m} /n)$. Note that 
\begin{align*}
& \hat g(\beta_0,  \hat \bm \eta) - \hat 	g( \beta_0, \hat \bm \eta_{p},  \bm \eta_{np0})  \\
 &= \frac{1}{n} \sum_{i=1}^{n}    \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \left[ - \{\hat\omega(\bm{X}_i; \hat{\bm \mu}, \hat{\bm \lambda}) - \omega_0(\bm{X}_i) \} + \beta_0 \{ \hat\theta(\bm{X}_i; \hat{\bm\mu})- \theta_0(\bm{X}_i)\} \right] +\text{Rem}_b\\
 &= \frac{1}{n} \sum_{i=1}^{n}    \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \left[ - \{\hat \omega(\bm{X}_i; {\bm \mu}_0, {\bm \lambda}_0 ) - \omega_0(\bm{X}_i; \bm\mu_0,{\bm \lambda}_0) \} + \beta_0 \{ \hat\theta(\bm{X}_i; {\bm \mu}_0) -  \theta_0(\bm{X}_i; {\bm \mu}_0)\} \right]  \\
&\qquad + \frac{1}{n} \sum_{i=1}^{n}   \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \left[ - \{\hat\omega(\bm{X}_i; \hat{\bm \mu}, \hat{\bm \lambda}) - \hat\omega(\bm{X}_i; {\bm \mu}_0, {\bm \lambda}_0) \} + \beta_0 \{ \hat\theta(\bm{X}_i; \hat{\bm\mu})- \hat\theta(\bm{X}_i; {\bm \mu}_0)\} \right] \\
 &\qquad+\text{Rem}_b\\
 &:= B_1+B_2+\text{Rem}_b 
\end{align*}  



For $ B_1 $, we  closely follow the steps in \citet[Chapter 8]{Newey1994_handbook} to  show that 
\begin{align}
\left\|	\frac1n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \{\hat\theta(\bm{X}_i; \bm \mu_0 )   - \theta_0(\bm{X}_i; \bm \mu_0 ) \} \right\|= o_p(n^{-1/2} )+ O_p(\sqrt{m}/n). \label{eq: kernel}
\end{align}
The other term in $ B_1 $ can be shown in the same way.  First, we  rewrite the nuisance parameter as $ \hat\theta(\bm x; \bm \mu_0 ) =\hat \gamma_2 (\bm x; \bm \mu_0 ) /\hat\gamma_1(\bm x)  $  and $ \theta_0(\bm x; \bm \mu_0 ) = \gamma_{20} (\bm x; \bm \mu_0 ) /\gamma_{10}(\bm x)  $, where 
 \begin{align*}
 	&\hat\gamma_2(\bm x; \bm \mu_0) =\frac1n \sum_{k=1}^{n}  (A_k - \bm{V}_k^T \bm\mu_0)^2K_{\sigma} (\bm x - \bm{X}_k), 	\hat\gamma_1(\bm x ) =\frac1n \sum_{k=1}^{n} K_{\sigma} (\bm x - \bm{X}_k), \\
 	&\gamma_{20} (\bm x; \bm \mu_0 ) = f_0(\bm x) E\{ (A - \bm{V}^T \bm\mu_0)^2\mid \bm X= \bm x \}, \gamma_{10}(\bm x) = f_0(\bm x),
  \end{align*}
where $ K_\sigma (\bm x ) = \sigma^{-d_x} K(\bm x/\sigma)$, $ d_x $ is the dimension of $ \bm{X} $, $ K(u) $ is a function satisfying Assumption \ref{assump: kernel},  $ \sigma $ is a bandwidth term, and $ f_0(\bm x) $ is the density of $ \bm x $. Then, we obtain the linearization (an functional analogue of  Taylor expansion) of $  \big( \bm{Z}-\bm D \bm\pi_0 \big)  \{\hat\theta(\bm{X}; \bm \mu_0 )   - \theta_0(\bm{X},\bm \mu_0 ) \}$  in \eqref{eq: kernel} as  $ L(\bm O;\hat  \gamma- \gamma_0, \bm \mu_0) = L(\bm O;\hat  \gamma, \bm \mu_0) - L(\bm O; \gamma_0, \bm \mu_0) $,  where
\begin{align*}
 L(\bm O; \gamma, \bm \mu_0)  = (\bm Z - \bm D\bm\pi_0 ) f_0(\bm{X})^{-1} \{-  \theta_0(\bm{X}; \bm \mu_0) \gamma_1(\bm{X}) + \gamma_2(\bm{X}; \bm \mu_0) \},
\end{align*}
and  $ \gamma =( \gamma_1(\bm x), \gamma_2(\bm x; \bm\mu_0) )$, $ \gamma_0 =( \gamma_{10}(\bm x), \gamma_{20}(\bm x; \bm\mu_0) )$.  With $ f_0(\bm x)$ and $ \gamma_1(\bm x) $ being bounded away from zero, $ \gamma_{20} (\bm x; \bm \mu_0) $ being bounded,  the remainder term from the linearization  satisfies
\begin{align}
	&\left\| (\bm{Z} - \bm D \bm \pi_0) \{\hat \gamma_2(\bm{X}; \bm \mu_0)/ \hat \gamma_1(\bm{X}) - \theta_0(\bm{X}; \bm \mu_0)\}-   L(\bm O; \hat \gamma- \gamma_0 , \bm \mu_0)  \right\| \nonumber\\
	&\leq \| \bm{Z} - \bm D \bm\pi_0 \| \sup_{\bm x\in \text{supp} (\bm{X})} \|\hat \gamma(\bm x; \bm \mu_0)- \gamma_0 (\bm x)\|^2 \leq C \sqrt{m} \sup_{\bm x\in \text{supp} (\bm{X})} \|\hat \gamma(\bm x; \bm \mu_0)- \gamma_0 (\bm x)\|^2 , \nonumber
\end{align}
where $ \text{supp} (\bm{X}) $ is the support of $ \bm{X} $. The above term is  $ o_p(n^{-1/2}) $ from  Lemma 8.10 of \cite{Newey1994_handbook} and  choosing the bandwidth $ \sigma $ to satisfy $ \sigma^4 \sqrt{nm}\rightarrow0 $ and $ \sigma^{d_x} \sqrt{n}/(\sqrt{m} \log n)\rightarrow\infty $ as $ n\rightarrow\infty $  in Assumption \ref{assump: kernel}. This means that 
\begin{align*}
	\frac1n \left\| \sum_{i=1}^{n} (\bm{Z}_i - \bm D_i \bm \pi_0) \{\hat \gamma_2(\bm{X}_i; \bm \mu_0)/ \hat \gamma_1(\bm{X}_i) - \theta_0(\bm{X}_i; \bm \mu_0)\}-   L(\bm O_i; \hat \gamma- \gamma_0 , \bm \mu_0)  \right\| = o_p(n^{-1/2}). 
\end{align*}

Write $ \frac1n  \sum_{i=1}^{n} L(\bm O_i; \hat\gamma- \gamma_0; \bm\mu_0 )=  \frac1n  \sum_{i=1}^{n} L(\bm O_i; \hat\gamma- \bar \gamma; \bm\mu _0 ) + \frac1n  \sum_{i=1}^{n} L(\bm O_i; \bar\gamma- \gamma_0; \bm\mu_0 )$, where $ \bar \gamma= E(\hat\gamma) $. Next we show
\begin{align*}
	&\frac1n \| \sum_{i=1}^{n} L(\bm O_i; \hat\gamma- \gamma_0; \bm\mu_0 ) \| \leq \frac1n  \|   \sum_{i=1}^{n} L(\bm O_i; \hat\gamma- \bar \gamma; \bm\mu _0 ) \| + \frac1n  \| \sum_{i=1}^{n} L(\bm O_i; \bar\gamma- \gamma_0; \bm\mu_0 ) \|  \\
	&=O_p(\sqrt{m}/n ) .
\end{align*}
 The definition of $ L(\bm O; \gamma, \bm\mu_0) $, boundedness of $ \bm{Z}, \bm{X} $, and Assumption \ref{assump: kernel}(ii) 
  give that \\  $ \|L(\bm O; \gamma, \bm\mu_0)  \|\leq C\sqrt{m} \|\gamma \| $,  which implies that $ \|L(\bm O; \bar \gamma- \gamma_0, \bm\mu_0)  \|^2 \leq C m \|\bar \gamma- \gamma \|^2 $. From $ E( L(\bm O; \gamma, \bm\mu_0))  = 0$,  we  have that 
 \begin{align*}
 	E\left( \|  \frac1n  \sum_{i=1}^{n} L(\bm O_i; \bar\gamma- \gamma_0; \bm\mu_0 ) \|^2  \right) =\frac{1}{n^2}  \sum_{i=1}^{n}  E\left\{ \|   L(\bm O_i; \bar\gamma- \gamma_0; \bm\mu_0 ) \|^2  \right\} \leq \frac{Cm \|\bar\gamma - \gamma_0\|^2}{n}. 
 \end{align*}
Hence, $\|  \frac1n  \sum_{i=1}^{n} L(\bm O_i; \bar\gamma- \gamma_0; \bm\mu_0 ) \|   = o_p(n^{-1/2})$  from Markov inequality and  $m \|\bar\gamma- \gamma_0 \|^2= O(\sigma^4m )\rightarrow 0 $, a result from  \citet[Lemma 8.9]{Newey1994_handbook} and the choice of bandwidth $ \sigma $ in Assumption \ref{assump: kernel}(iii).
Then, we deal with $   \frac1n  \sum_{i=1}^{n} L(\bm O_i; \hat\gamma- \bar \gamma; \bm\mu_0 ) $. Let 
\begin{align*}
  &m(\bm O_i , \bm O_k) = (\bm{Z}_i -\bm D_i \bm\pi_0 ) f_0(\bm{X}_i)^{-1} \left\{ - \theta_0 (\bm{X}_i;\bm\mu_0 ) K_\sigma(\bm{X}_i - \bm{X}_k)  + (A_k - \bm{V}_k^T \bm \mu_0  )^2  K_\sigma(\bm{X}_i - \bm{X}_k )\right\}, \\
  &m_2(\bm O_k ) = \int m (\bm O_i, \bm O_k) dP_0(\bm O_i)  = 0, \\
  & m_1(\bm O_i ) = \int m (\bm O_i, \bm O_k) dP_0(\bm O_k) = L(\bm O_i; \bar\gamma, \bm \mu_0 ).
\end{align*}
We can write $   \frac1n  \sum_{i=1}^{n} L(\bm O_i; \hat\gamma- \bar \gamma; \bm\mu ) $ in the form of a  V-statistic 
\begin{align*}
	&\left\| \frac1n  \sum_{i=1}^{n} L(\bm O_i; \hat\gamma- \bar \gamma; \bm\mu_0  ) \right\|\\
	&=  \left\|  \frac1n  \sum_{i=1}^{n} L(\bm O_i; \hat\gamma; \bm\mu_0  ) -  \frac1n  \sum_{i=1}^{n} L(\bm O_i;\bar \gamma; \bm\mu_0  ) \right\| \\
		&=\left\|  n^{-2} \sum_{i=1}^{n} \sum_{k=1}^{n} m(\bm O_i, \bm O_j) - n^{-1} \sum_{i=1}^{n} m_1(\bm O_i)  \right\| \\
		&= \left\| n^{-2} \sum_{i=1}^{n} \sum_{k=1}^{n} m(\bm O_i, \bm O_j) - n^{-1} \sum_{i=1}^{n} m_1(\bm O_i)  - n^{-1} \sum_{i=1}^{n} m_2(\bm O_i) + E\{ m_1(\bm O)\}  \right\|\\
		&= O_p(\sqrt{m}/n ) 
\end{align*}
where the last line is from Lemma 8.4 of \cite{Newey1994_handbook}. This concludes the proof of \eqref{eq: kernel} from the triangle inequality. 

For $ B_2 $, we show that 
\begin{align}
	\left\|	\frac1n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \{\hat\theta(\bm{X}_i; \hat{\bm \mu} )   -\hat \theta(\bm{X}_i; \bm \mu_0 ) \} \right\|= o_p(m \sqrt{\log m}/n)+ O_p(n^{-1} m \sqrt{m\log m/n}). \nonumber
\end{align}
The other term in $ B_2 $ can be shown in the same way.  Let $ \hat \gamma_3(\bm x) = \frac1n\sum_{k=1}^{n} (A_k - \bm{V}_k^T \bm\mu_0) \bm{V}_k^T K_\sigma(\bm x- \bm{X}_k) $ and  $ \hat \gamma_{3j}(\bm x) = \frac1n\sum_{k=1}^{n} (A_k - \bm{V}_{k}^T \bm\mu_0) \bm{V}_{kj} K_\sigma(\bm x- \bm{X}_k) $, where $  \hat \gamma_{3j}(\bm x) $ is the $ j $th component of $  \hat \gamma_3(\bm x) $. Using  triangle inequality and Strong Schwartz Matrix Inequality, we write
\begin{align}
&\left\| \frac1n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \{\hat\theta(\bm{X}_i; \hat{\bm \mu} )   -\hat \theta(\bm{X}_i; \bm \mu_0 ) \}    \right\|\nonumber\\
&= \left\| - \frac2n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \frac{\hat{\gamma}_3(\bm{X}_i)}{\hat\gamma_1(\bm{X}_i)} (\hat{\bm\mu}- \bm \mu_0)  + \text{Rem}_c\right\|\nonumber \\ 
&\leq  \left\|  \frac2n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \frac{\hat{\gamma}_3(\bm{X}_i)}{\hat\gamma_1(\bm{X}_i)} (\hat{\bm\mu}- \bm \mu_0) \right\| +\left\| \text{Rem}_c\right\|\nonumber \\ 
&\leq  \left\|  \frac2n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \frac{\hat{\gamma}_3(\bm{X}_i)}{\hat\gamma_1(\bm{X}_i)} \right\|\left\|(\hat{\bm\mu}- \bm \mu_0) \right\| +\left\| \text{Rem}_c\right\| \label{eq: B2}
\end{align}
where \begin{align*}
	\text{Rem}_c= (\hat{\bm\mu}- \bm\mu_0 )^T  \left\{\frac1n \sum_{i=1}^{n} (\bm{Z}_i - \bm D_i \bm\pi_0 )   \frac{\frac1n \sum_{k=1}^{n} \bm{V}_k \bm{V}_k^T K_\sigma(\bm{X}_i - \bm{X}_k)}{\frac{1}{n} \sum_{k=1}^{n} K_\sigma (\bm{X}_i - \bm{X}_k)} \right\} (\hat{\bm\mu}- \bm\mu_0 ). 
\end{align*}
Note that we have shown above that  $ \left\|(\hat{\bm\mu}- \bm \mu_0) \right\| = O_p(\sqrt{m\log m/n} )$. Because $ E\{(A - \bm{V}^T \bm\mu_0 )\bm{V}^T \mid \bm{X}\} = 0$, the true conditional expectation that $\hat\gamma_3(\bm{X}_i)/\hat\gamma_1(\bm{X}_i) $ is estimating is zero. We
 can use the same argument as in the proof of \eqref{eq: kernel} to show that 
\begin{align*}
	  &\left\|  \frac2n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \frac{\hat{\gamma}_3(\bm{X}_i)}{\hat\gamma_1(\bm{X}_i)} \right\|^2\leq   \left\|  \frac2n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \frac{\hat{\gamma}_3(\bm{X}_i)}{\hat\gamma_1(\bm{X}_i)} \right\|_F^2  \\
	  &= \sum_{k=1}^{m+d_x}    \left\|  \frac2n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \frac{\hat{\gamma}_{3k}(\bm{X}_i)}{\hat\gamma_1(\bm{X}_i)} \right\|^2  = o_p(m/n)+ O_p(m^2/n^2). 
\end{align*}
Since the remainder term $ \text{Rem}_c $ contains the higher order terms, we conclude that \eqref{eq: B2} is $ o_p(m\sqrt{\log m}/n) + O_p( n^{-1} m\cdot \sqrt{m\log m/n})$. 



(ii) Because $ g_i(\beta, \bm \eta) $ is linear in $ \beta $, $ G_i(\bm \eta) $ inherits its nice property in terms of the nuisance parameters. In other words, we still have 
