		 &\leq  \|\hat\Omega(\beta_0,\hat \bm \eta)  - \hat \Omega(\beta_0, \bm \eta_0) \| +\|	 \hat \Omega(\beta_0, \bm \eta_0) - \Omega \| \\
		 & \leq \left\|  \frac{1}{n} \sum_{i=1}^{n} (\bm{Z}_i - \bm D_i \hat{\bm\pi}) (\bm{Z}_i - \bm D_i \hat{\bm\pi})^T \hat\Delta_{i0}^2-(\bm{Z}_i - \bm D_i {\bm\pi}_0) (\bm{Z}_i - \bm D_i {\bm\pi}_0)^T \Delta_{i0}^2  \right\|\\
		 & \qquad+  \left\|  \frac{1}{n} \sum_{i=1}^{n} (\bm{Z}_i - \bm D_i \hat{\bm\pi}) (\bm{Z}_i - \bm D_i \hat{\bm\pi})^T \hat\Delta_{i0}(\hat\omega(\bm{X}_i)- \beta_0\hat\theta(\bm{X}_i)) \right.\\
		 & \qquad\qquad\qquad\qquad \left.-(\bm{Z}_i - \bm D_i {\bm\pi}_0) (\bm{Z}_i - \bm D_i {\bm\pi}_0)^T \Delta_{i0}(\omega_0(\bm{X}_i)- \beta_0\theta_0(\bm{X}_i)) \right\|\\
		 &\qquad + \left\|  \frac{1}{n} \sum_{i=1}^{n} (\bm{Z}_i - \bm D_i \hat{\bm\pi}) (\bm{Z}_i - \bm D_i \hat{\bm\pi})^T(\hat\omega(\bm{X}_i)- \beta_0\hat\theta(\bm{X}_i))^2  \right.\\
		 &\qquad\qquad\qquad\qquad \left.-(\bm{Z}_i - \bm D_i {\bm\pi}_0) (\bm{Z}_i - \bm D_i {\bm\pi}_0)^T (\omega_0(\bm{X}_i)- \beta_0\theta_0(\bm{X}_i))^2  \right\|\\
		 &\qquad +\|	 \hat \Omega(\beta_0, \bm \eta_0) - \Omega \| \\
		 &:= \|I_1\|+\|I_2\|+\|I_3\|+\|I_4\|.
	\end{align*}

A key technique we use here is to vectorize the matrix, then a proof very similar to the proof of Lemma \ref{lemma: g beta, nuisance} will establish the result. Specifically, since $ \|I_1\|\leq \|I_1\|_F= \|\text{vec} (I_1)\| $, where $ \text{vec}(A)= (a_1^T, \dots, a_m^T)^T\in \mathbb{R}^{mn}  $ for a matrix $ A= (a_1, \dots, a_m) \in\mathbb{R}^{n\times m}$.  

Let $ \otimes $ be the Kronecker product. For $  \text{vec} (I_1) $, 
	\begin{align}
	 & \text{vec} (I_1)  \nonumber \\
		& = \nabla_{\bm \eta_p}  \left[ \frac{1}{n} \sum_{i=1}^{n}  (\bm{Z}_i - \bm D_i {\bm\pi}_0) \otimes  (\bm{Z}_i - \bm D_i {\bm\pi}_0) \Delta_i^2  \right]  (\hat{\bm \eta}_p- \bm \eta_{p0}) + \text{Rem}_d \nonumber\\
		&= - \frac1n \sum_{i=1}^{n} \Delta_i^2 (\bm{Z}_i - \bm D_i \bm\pi_0 ) \otimes  \bm D_i (\hat{\bm\pi}- \bm\pi_0 )  - \frac1n \sum_{i=1}^{n} \Delta_i^2  \{ \bm D_i (\hat{\bm\pi}- \bm\pi_0 )\}\otimes (\bm{Z}_i - \bm D_i \bm\pi_0 ) \nonumber\\
		&\qquad + \frac{1}{n} \sum_{i=1}^{n}  (\bm{Z}_i - \bm D_i {\bm\pi}_0) \otimes  (\bm{Z}_i - \bm D_i {\bm\pi}_0) 2\Delta_i (A_i - \bm{V}_i^T \bm\mu_0) \bm{V}_i^T (\hat{\bm \lambda}- \bm\lambda_0) \nonumber \\
		&\qquad + \frac{1}{n} \sum_{i=1}^{n}  (\bm{Z}_i - \bm D_i {\bm\pi}_0) \otimes  (\bm{Z}_i - \bm D_i {\bm\pi}_0) 2\Delta_i (- Y_i + 2\beta_0 A_i + \bm{V}_i^T \bm\lambda_0 - 2\beta_0 \bm{V}_i^T\bm\mu_0) \bm{V}_i^T (\hat{\bm \mu}- \bm\mu_0)\nonumber\\
		&\qquad + \text{Rem}_d.  \label{eq: vec I1}
	\end{align}
For the above first term, from the Strong Schwartz Matrix Inequality, 
\begin{align*}
	& \left\| \frac1n \sum_{i=1}^{n} \Delta_i^2 (\bm{Z}_i - \bm D_i \bm\pi_0 ) \otimes  \bm D_i (\hat{\bm\pi}- \bm\pi_0 )  \right\|^2 \nonumber\\
	&= \sum_{j=1}^{m}   	\left\| \frac1n \sum_{i=1}^{n} \Delta_i^2 (\bm{Z}_i - \bm D_i \bm\pi_0 )   \bm X_i^T (\hat{\bm\pi}_j- \bm\pi_{j0} )  \right\|^2  \\
	&\leq 	\left\| \frac1n \sum_{i=1}^{n} \Delta_i^2 (\bm{Z}_i - \bm D_i \bm\pi_0 )   \bm X_i^T   \right\|^2  \sum_{j=1}^{m}     \left\| \hat{\bm\pi}_j- \bm\pi_{j0}  \right\|^2 \\
	&= 	\left\| \frac1n \sum_{i=1}^{n} \Delta_i^2 (\bm{Z}_i - \bm D_i \bm\pi_0 )   \bm X_i^T   \right\|^2    \left\| \hat{\bm\pi}- \bm\pi_{0}  \right\|^2 \\
	&= O_p(m^2(\log m)^2/n^2),
\end{align*} 
where the last expression is obtained using the same argument as in the derivation  of $ A_{21} $ in the proof of Lemma \ref{lemma: g beta, nuisance}, and $ \| \hat{\bm\pi} - \bm\pi_0 \|^2  = O_p (m\log m/n ) $ derived after \eqref{eq: pi}. The second term in \eqref{eq: vec I1} has the same norm as the first term in \eqref{eq: vec I1}.  For the third term in \eqref{eq: vec I1}, we have 
\begin{align*}
	&\left\| \frac{1}{n} \sum_{i=1}^{n}  (\bm{Z}_i - \bm D_i {\bm\pi}_0) \otimes  (\bm{Z}_i - \bm D_i {\bm\pi}_0) 2\Delta_i (A_i - \bm{V}_i^T \bm\mu_0) \bm{V}_i^T (\hat{\bm \lambda}- \bm\lambda_0) \right\|^2 \\
	&= \sum_{j=1}^{m} \left\| \frac{1}{n} \sum_{i=1}^{n}  (\bm{Z}_i - \bm D_i {\bm\pi}_0)   (Z_{ij} - \bm X_i^T  {\bm\pi}_{j0}) 2\Delta_i (A_i - \bm{V}_i^T \bm\mu_0) \bm{V}_i^T (\hat{\bm \lambda}- \bm\lambda_0) \right\|^2 \\
	&\leq  \sum_{j=1}^{m} \left\| \frac{1}{n} \sum_{i=1}^{n}  (\bm{Z}_i - \bm D_i {\bm\pi}_0)   (Z_{ij} - \bm X_i^T  {\bm\pi}_{j0}) 2\Delta_i (A_i - \bm{V}_i^T \bm\mu_0) \bm{V}_i^T \right\|^2 \| \hat{\bm \lambda}- \bm\lambda_0\|^2 \\
	& =  \sum_{j=1}^{m} \left\| \sum_{i=1}^{n}  S_{ij} \right\|^2 \| \hat{\bm \lambda}- \bm\lambda_0\|^2 ,
\end{align*}
where $ S_{ij} = \frac1n (\bm{Z}_i - \bm D_i {\bm\pi}_0)   (Z_{ij} - \bm X_i^T  {\bm\pi}_{j0}) 2\Delta_i (A_i - \bm{V}_i^T \bm\mu_0) \bm{V}_i^T  $. Then, we calculate the matrix variance parameter 
\begin{align*}
v_j &= n \|E(S_{ij} S_{ij}^T )\| \\
&= n^{-1}  \left\|E[(\bm{Z}_i - \bm D_i {\bm\pi}_0)  (\bm{Z}_i - \bm D_i {\bm\pi}_0)^T  \{ (Z_{ij} - \bm X_i^T  {\bm\pi}_{j0}) 2\Delta_i (A_i - \bm{V}_i^T \bm\mu_0)\}^2  \bm{V}_i^T \bm{V}_i  ] \right\|\\
&\leq C n^{-1} m   \left\|E[(\bm{Z}_i - \bm D_i {\bm\pi}_0)  (\bm{Z}_i - \bm D_i {\bm\pi}_0)^T  \{  \Delta_i (A_i - \bm{V}_i^T \bm\mu_0)\}^2   ] \right\|\\
& \leq Cn^{-1} m  
\end{align*}
and  the large deviation parameter 
\begin{align*}
	L_j^2  &= E\left( \max_i \|S_{ij }\|^2\right) \leq Cn^{-2} m^2 E\left\{ \max_i (\Delta_i^2 (A_i - \bm{V}_i^T \bm\mu_0)^2)\right\} \leq Cn^{-2} m^2 (\log n )^8,
\end{align*}
where the last inequality is from Assumption \ref{assump: moment} and \cite{buhlmann2011statistics}.  Hence, we have from \citet[Theorem 1]{tropp2015expected} that 
\begin{align*}
	E\left( \sum_{j=1}^{m} \left\| \sum_{i=1}^{n}  S_{ij} \right\|^2\right) \leq \frac{m^2\log m}{n}.
\end{align*}
This combined with Markov inequality, we have that $ \sum_{j=1}^{m} \left\| \sum_{i=1}^{n}  S_{ij} \right\|^2= O_p (m^2\log m/n) $. This implies the third term in \eqref{eq: vec I1} is
\begin{align*}
	&\left\| \frac{1}{n} \sum_{i=1}^{n}  (\bm{Z}_i - \bm D_i {\bm\pi}_0) \otimes  (\bm{Z}_i - \bm D_i {\bm\pi}_0) 2\Delta_i (A_i - \bm{V}_i^T \bm\mu_0) \bm{V}_i^T (\hat{\bm \lambda}- \bm\lambda_0) \right\|^2  = O_p\left(\frac{m^3(\log m)^2}{n^2}\right)
\end{align*}
The other proofs are very similar to the derivations in the proof of Lemma \ref{lemma: g beta, nuisance} and are omitted. Hence, we have shown that $ \|I_1\| = O_p(m^{3/2}\log m/n) $. 


We similarly vectorize  $ I_3 $ and analyze $ {\rm vec}(I_3) $, following the steps in the proof of Lemma \ref{lemma: g beta, nuisance}. First, we show that 
	\begin{align}
		\left\|	\frac1n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big) \otimes\big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \{\hat\theta^2(\bm{X}_i; \bm \mu )   - \theta_0^2(\bm{X}_i; \bm \mu ) \} \right\|  =  o_p(\sqrt{m/n}) \label{eq: Omega, kernel}.
	\end{align}
Following the notations in \eqref{eq: kernel}. We obtain the linearization of $		\frac1n \sum_{i=1}^{n}  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big) \otimes\big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \{\hat\theta^2(\bm{X}_i; \bm \mu )   - \theta_0^2(\bm{X}_i; \bm \mu ) \} $ as $ \frac1n \sum_{i=1}^{n} L(\bm O_i; \hat\gamma- \gamma_0, \bm \mu) = \frac1n \sum_{i=1}^{n} \{ L(\bm O_i; \hat\gamma, \bm \mu) -  L(\bm O_i; \gamma_0, \bm \mu) \} $, where 
\begin{align*}
	 L(\bm O; \gamma, \bm \mu) =   \big( \bm{Z}-\bm D \bm\pi_0 \big) \otimes\big( \bm{Z}-\bm D \bm\pi_0 \big) 2\theta_0 (\bm{X}; \bm\mu) f_0(\bm{X})^{-1} \{-\theta_0(\bm{X}; \bm\mu) \gamma_1(\bm{X}) + \gamma_2(\bm{X}; \bm\mu)\}, 
\end{align*}
and the remainder term from the linearlization is $ o_p(\sqrt{m/n}) $. Then, we have $ \|\frac{1}{n}\sum_{i=1}^{n}L(\bm O_i;\hat\gamma- \gamma_0; \bm\mu ) \|=  O_p(m/n)$. Thus, we have that \eqref{eq: Omega, kernel} is of order $ o_p(\sqrt{m/n}) $. We can also show that $ 	\left\|	\frac1n \sum_{i=1}^n  \big( \bm{Z}_i-\bm D_i \bm\pi_0 \big) \otimes\big( \bm{Z}_i-\bm D_i \bm\pi_0 \big)  \{\hat\theta^2(\bm{X}_i; \hat {\bm \mu} )   -\hat \theta^2(\bm{X}_i; \bm \mu_0 ) \} \right\|  =  o_p(\sqrt{m^3\log m}/n) $. The other terms in $ I_3 $ can be shown similarly. Therefore, $\|I_3\|\leq  \|I_3\|_F =  \|{\rm vec} (I_3)\| = o_p(\sqrt{m/n})  +  o_p(\sqrt{m^3\log m}/n)$.  


Next, notice that $\| I_2\| $ can be bounded by 
\begin{align*}
 &  \bigg\|  \frac{1}{n} \sum_{i=1}^{n}\left\{ (\bm{Z}_i - \bm D_i \hat{\bm\pi}) (\bm{Z}_i - \bm D_i \hat{\bm\pi})^T \hat\Delta_i -(\bm{Z}_i - \bm D_i {\bm\pi}_0 ) (\bm{Z}_i - \bm D_i {\bm\pi_0})^T \Delta_i \right\} (\omega_0(\bm{X}_i)- \beta_0\theta_0(\bm{X}_i))\bigg\|\\
	  + &\bigg\|  \frac{1}{n} \sum_{i=1}^{n}(\bm{Z}_i - \bm D_i {\bm\pi}_0 ) (\bm{Z}_i - \bm D_i {\bm\pi_0})^T \Delta_i (\hat\omega(\bm{X}_i)- \beta_0\hat\theta(\bm{X}_i) - \omega_0(\bm{X}_i) + \beta_0 \theta_0(\bm{X}_i) )\bigg\|\\
	  +& \|\text{Rem}_I\|
\end{align*}  
where $ \text{Rem}_I $ is a higher order term, the above first term can be bounded in the same way as $ I_1 $, the above second term can be bounded in the same way as $ I_3 $. 



	Finally, we again use the matrix concentration inequality \citet[Theorem 1]{tropp2015expected}  to show that $ \|I_4\|= 	\|\hat \Omega(\beta_0, \bm \eta_0)-  \Omega(\beta_0, \bm \eta_0)\| =O_p(\sqrt{m\log m/n}) $. We can show that the matrix variance parameter $ v \leq Cm/n$ and the large deviation parameter $ L^2 \leq Cm\log n/n^2$.  Hence, the matrix variance parameter term $ v $ drives the order, and  $ E	\|\hat \Omega(\beta_0, \bm \eta_0)-  \Omega(\beta_0, \bm \eta_0)\|^2\leq   m\log m/n $. The result follows  from Markov inequality. 


Combining the above arguments, we have that $ \|\hat{\Omega}(\beta_0,\bm \eta_0) - \Omega\| = O_p(\sqrt{m\log m/n}) + O_p(\sqrt{m^3(\log m)^2/n^2})$. 

